import { expect, it } from 'vitest';
import { diffHunkRows } from '../diffHunkRows';
import type { GitDiffHunk } from '../../../../../domain/core/diffs/gitDiffHunk';
const hunk: GitDiffHunk = { id: 'h', repositoryId: 'r', commit: 'c', parent: 'p', path: 'code.ts', status: 'M', kind: 'text',
  oldStart: 12, oldLines: 3, newStart: 20, newLines: 4,
  patch: '@@ -12,3 +20,4 @@\n context\n-old\n+new\n+extra\n last\n\\ No newline at end of file\n' };
it('keeps independent old/new coordinates and syntax streams through an unequal replacement', () => {
  const { rows, before, after } = diffHunkRows(hunk);
  expect(rows.map(({ kind, oldLine, newLine }) => [kind, oldLine, newLine])).toEqual([
    ['context', 12, 20], ['delete', 13, undefined], ['add', undefined, 21], ['add', undefined, 22], ['context', 14, 23]
  ]);
  expect(before).toEqual(['context', 'old', 'last']); expect(after).toEqual(['context', 'new', 'extra', 'last']);
  for (const row of rows) {
    if (row.oldIndex !== undefined) expect(before[row.oldIndex]).toBe(row.text);
    if (row.newIndex !== undefined) expect(after[row.newIndex]).toBe(row.text);
  }
  expect(rows.at(-1)?.noNewline).toBe(true);
});
it('handles empty sides, blank lines, literal markup, and no-newline markers on both sides', () => {
  const parsed = diffHunkRows({ ...hunk, oldStart: 1, newStart: 1, patch: '@@ -1 +1,2 @@\n-<old>\n\\ No newline at end of file\n+\n+<new>\n\\ No newline at end of file\n' });
  expect(parsed.before).toEqual(['<old>']); expect(parsed.after).toEqual(['', '<new>']);
  expect(parsed.rows.map(r => r.noNewline ?? false)).toEqual([true, false, true]);
  expect(diffHunkRows({ ...hunk, oldStart: 0, newStart: 1, patch: '@@ -0,0 +1 @@\n+first\n' }).rows[0]).toMatchObject({ kind: 'add', newLine: 1, newIndex: 0 });
  expect(diffHunkRows({ ...hunk, newStart: 0, patch: '@@ -12 +0,0 @@\n-last\n' }).after).toEqual([]);
});
it('does not interpret binary or metadata records as code', () => {
  expect(diffHunkRows({ ...hunk, kind: 'binary' })).toEqual({ rows: [], before: [], after: [] });
  expect(diffHunkRows({ ...hunk, kind: 'metadata' })).toEqual({ rows: [], before: [], after: [] });
});

import { expect, it } from 'vitest';
import { RevisionedDiagramService } from '../../../../../domain/core/diagrams/diagramService';
import { diffTreeNodes, diffTreeSummary, writeDiffTree } from '../../../../../domain/mapping/changes/diffTree';
import { identifyHunk } from '../../../../../domain/core/diffs/gitDiffHunk';
import { diffTreeCoverage } from '../diffTreeCoverage';

it('unions parent/child hunks once, excludes non-application code, and inherits explicit destinations', () => {
  const make = (path: string) => identifyHunk({ repositoryId: 'repo', commit: 'a'.repeat(40), parent: null, path, status: 'M', kind: 'text', oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, patch: '@@ -1 +1 @@\n-old\n+new\n' });
  const hunks = [make('src/app.ts'), make('src/other.ts'), make('src/__tests__/app.test.ts'), make('package-lock.json')];
  const target = { representationId: 'canvas', displayNodeId: 'grid:overview', contentNodeId: 'editor' };
  const tree = writeDiffTree(new RevisionedDiagramService(), { ascii: 'Root\n|-- Parent\n|   |-- Child\n|   `-- Inherited\n`-- Unmapped', mappings: [
    { id: 'parent', source: { line: 2 }, targets: [hunks[0], hunks[2]].map(h => ({ kind: 'diff-hunk', hunkId: h.id })), diagramTargets: [target] },
    { id: 'child', source: { line: 3 }, targets: [hunks[0], hunks[1]].map(h => ({ kind: 'diff-hunk', hunkId: h.id })) }
  ] }, hunks);
  const coverage = diffTreeCoverage({ changeSessionId: 's', title: 'Review', status: 'draft', version: 0, hunks, total: 4, nextOffset: null, unmappedNodeIds: [],
    diffTree: { ...diffTreeSummary(tree), diagram: tree.revision.diagram, nodes: diffTreeNodes(tree), mappings: tree.mappings } });
  const node = (label: string) => diffTreeNodes(tree).find(n => n.label === label)!.id;
  expect(coverage.stats(coverage.hunksFor(node('Parent')))).toEqual({ lines: 4, total: 4, hunks: 2, percent: 100 });
  expect(coverage.stats(coverage.hunksFor(node('Inherited'))).lines).toBe(2);
  expect(coverage.hunksFor(node('Unmapped')).size).toBe(0);
  expect(coverage.targetsFor(node('Child'))).toEqual([target]);
  expect(coverage.nodesForHunk(hunks[0].id)).toHaveLength(2);
});

import { afterEach, expect, it, vi } from 'vitest';
import { readDiffTree, type DiffTreeRead } from '../changeSessionApi';
import { prefetchDiffTree } from '../diffTreeData';
vi.mock('../changeSessionApi', () => ({ readDiffTree: vi.fn() }));
afterEach(() => vi.restoreAllMocks());

it('starts remaining pages in parallel, coalesces readers, and reuses patches for metadata changes', async () => {
  let now = 10000;
  vi.spyOn(Date, 'now').mockImplementation(() => now);
  const page = (offset: number, version = 0) => ({ version, total: 301, nextOffset: offset < 300 ? offset + 100 : null,
    commits: ['commit'], head: 'head', diffTree: { revisionId: `revision-${version}`, hunkCount: 301 },
    hunks: Array.from({ length: Math.min(100, 301 - offset) }, (_, i) => ({ id: String(offset + i), patch: '+added' })) }) as DiffTreeRead;
  const pending = new Map<number, (value: DiffTreeRead) => void>();
  vi.mocked(readDiffTree).mockImplementation(async (_id, input) => input.offset
    ? new Promise(resolve => pending.set(input.offset!, resolve)) : page(0));
  const first = prefetchDiffTree('parallel-test');
  expect(prefetchDiffTree('parallel-test')).toBe(first);
  await vi.waitFor(() => expect([...pending.keys()]).toEqual([100, 200, 300]));
  // All pages have started while none of the independent page reads has completed.
  pending.forEach((resolve, offset) => resolve(page(offset)));
  await first;
  expect(readDiffTree).toHaveBeenCalledTimes(4);
  await prefetchDiffTree('parallel-test');
  expect(readDiffTree).toHaveBeenCalledTimes(4);
  now += 2000;
  vi.mocked(readDiffTree).mockResolvedValue(page(0, 1));
  await prefetchDiffTree('parallel-test');
  expect(readDiffTree).toHaveBeenCalledTimes(5);
  expect(vi.mocked(readDiffTree).mock.lastCall?.[1].includePatches).toBe(false);
});

